// Extract reference array dynamically and safely handle the stringified JSON format
let referenceVar = [];
try {
  let rawReference = $('Code in JavaScript1').item.json.JSON.result;

  // If it's a string, parse it into an actual array
  if (typeof rawReference === 'string') {
    referenceVar = JSON.parse(rawReference);
  } else {
    referenceVar = rawReference || [];
  }
} catch (e) {
  // Safe catch block in case parsing fails
}

const backupDate = new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString().split('T')[0];

// Helper: Match assignee string to an ID from referenceVar
function findIdAndNormalize(assigneeStr) {
  let cleanName = assigneeStr.replace(/[\[\]]/g, '').trim(); 

  if (cleanName === "Julian" || cleanName === "Julienne") cleanName = "Julienne Mae Anito";
  if (cleanName === "Cara") cleanName = "Cara Erika Mortillero";
  if (cleanName === "Claire") cleanName = "Claire Vergara";
  if (cleanName === "Relben") cleanName = "Relben Tantio";

  if (!Array.isArray(referenceVar)) return { id: "Unassigned", fullName: "Unassigned" };

  const match = referenceVar.find(r => r.name.toLowerCase().includes(cleanName.toLowerCase()));

  return {
    id: match ? match.id : "Unassigned",
    fullName: match ? match.name : "Unassigned"
  };
}

const finalTasks = [];

// Split on BOTH actual newlines and explicit literal '\n' characters
const lines = inputData.split(/\\n|\n/);

// 2. Loop through every single parsed line
for (let line of lines) {
  line = line.trim();

  // Look for lines containing target task markers: [Name] Task Title: Description
  if (line.startsWith('[') && line.includes(']')) {
    const closeBracketIdx = line.indexOf(']');
    const rawAssignee = line.substring(1, closeBracketIdx).trim();
    const remainingText = line.substring(closeBracketIdx + 1).trim();

    if (!remainingText) continue;

    // Split compound assignees (e.g., "[Marielle, Claire]")
    const assigneesArray = rawAssignee.split(/,|\band\b/).map(s => s.trim());

    for (const assignee of assigneesArray) {
      if (assignee.toLowerCase() === "the group") continue;

      const mapping = findIdAndNormalize(assignee);
      if (mapping.id === "Unassigned") continue; // Keep your filter: skip unmatched IDs

      // Dynamically calculate simple priorities based on content
      let priority = "Medium";
      if (/urgent|immediately|critical|fix|deactivate/i.test(remainingText)) priority = "High";
      if (/research|explore|review|compare/i.test(remainingText)) priority = "Low";

      // Dynamically calculate due dates based on content markers
      let due_date = backupDate; 
      if (/this Wednesday/i.test(remainingText)) due_date = "2026-05-20"; 
      if (/tomorrow/i.test(remainingText)) due_date = "2026-05-19";
      if (/November 12/i.test(remainingText)) due_date = "2026-11-12";

      finalTasks.push({
        name: remainingText.replace(/^:\s*/, ''), // Strips any leading colons cleanly
        assignee: mapping.fullName,
        id: mapping.id,
        priority: priority,
        due_date: due_date
      });
    }
  }
}

// 3. Output safe message structure if no target data matches
if (finalTasks.length === 0) {
