function getGmailFormattedDate(isoString, daysToShift) {
    const date = new Date(isoString);
    date.setDate(date.getDate() + daysToShift);

    // Extract UTC year, month, and day to avoid local timezone shifts
    const yyyy = date.getUTCFullYear();
    const mm = String(date.getUTCMonth() + 1).padStart(2, '0'); // Months are 0-indexed
    const dd = String(date.getUTCDate()).padStart(2, '0');

    return `${yyyy}/${mm}/${dd}`;
}

