// 1. Fetch text dynamically using the n8n v1+ data selector syntax
const inputText = $('Get many messages').first().json.text || "";

const tasks = [];

// 2. Isolate the explicit "Action Items" block
const actionItemsSection = inputText.split("Action Items ✨")[1]?.split("Meeting Summary ✨")[0] || "";

if (actionItemsSection) {
  // Split by double newlines to isolate each distinct action item block
  const blocks = actionItemsSection.split(/\n\s*\n/);

  for (let block of blocks) {
    // Look for /share/ or /calls/ to match the text structure safely
    if (block.includes("https://fathom.video/share/") || block.includes("https://fathom.video/calls/")) {

      // Clean up internal breaks to make it a continuous single-line string
      let cleanedBlock = block.replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();

      // Strip out image URLs and tracking URLs
      cleanedBlock = cleanedBlock
        .replace(/\[https:\/\/storage\.googleapis\.com[^\]]+\]/g, '')
        .replace(/\[https:\/\/fathom\.video\/(?:calls|share)\/[^\]]+\]/g, '')
        .trim();

      // Attempt to match an assignee (looks for 1 to 3 capitalized words at the very end)
      const nameMatch = cleanedBlock.match(/\s+([A-Z][a-zA-Z]+(?:\s[A-Z][a-zA-Z]+){0,2})\s*$/);

      let taskName = "";
      let assignee = "";

      if (nameMatch) {
        // If a name structure is found, separate the task and the assignee
        assignee = nameMatch[1].trim();
        taskName = cleanedBlock.substring(0, cleanedBlock.lastIndexOf(nameMatch[0])).trim();
      } else {
        // If no name structure matches at the end, the whole text is the task
        taskName = cleanedBlock;
        assignee = "Claire Vergara";
      }

      // Strip trailing/leading punctuation, markdown artifacts, or timestamps leftovers
      taskName = taskName
        .replace(/[;\s-\*]+$/, '')
        .replace(/^[\s-\*]+/, '')
        .replace(/https:\/\/fathom\.video\/(?:calls|share)\/\S*/g, '')
        .trim();

      if (taskName) {
        tasks.push({
          name: taskName,
          assignee: assignee || "Claire Vergara" // Extra safety fallback
        });
      }
    }
  }
}

// 3. Return formatted as an array of items, each containing a 'json' object
return tasks.map(task => ({ json: task }));

// 1. Get all incoming items from the previous node
const items = $input.all();

// 2. Map through the items to create a formatted string for each task
const formattedTasks = items.map(item => {
  const name = item.json.name || 'No Task Name';
  const assignee = item.json.assignee || 'Unassigned';

  return `- ${name} (Assignee: ${assignee})`;
});

// 3. Join all the task strings with a newline character
const combinedText = formattedTasks.join('\n');

// 4. Return the result as a single text string inside an n8n-friendly format
return [
  {
    json: {
      taskListText: combinedText
    }
  }
];

